import{_ as t,o as i,c as l,a3 as e}from"./chunks/framework.DxEvSMU4.js";const p=JSON.parse('{"title":"T1 是否需要訓練的判斷","description":"","frontmatter":{},"headers":[],"relativePath":"train/t1-decide.md","filePath":"train/t1-decide.md","lastUpdated":1793029011000}'),r={name:"train/t1-decide.md"};function o(n,a,s,d,c,h){return i(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="t1-是否需要訓練的判斷" tabindex="-1">T1 是否需要訓練的判斷 <a class="header-anchor" href="#t1-是否需要訓練的判斷" aria-label="Permalink to &quot;T1 是否需要訓練的判斷&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境</li><li>狀態: 撰寫中 (僅有大綱)</li><li>資料基準日: 2026-10-26</li><li>待查證: 本章尚為大綱, 無事實性陳述, 撰寫時須補來源; 文中的類比為整理者所寫, 不代表技術上完全等同</li></ul></div><p><strong>本章要回答的問題</strong>: 我的需求用提示或檢索就能解決, 還是真的需要微調?</p><h2 id="t1-1-提示-檢索與微調的選擇" tabindex="-1">T1.1 提示, 檢索與微調的選擇 <a class="header-anchor" href="#t1-1-提示-檢索與微調的選擇" aria-label="Permalink to &quot;T1.1 提示, 檢索與微調的選擇&quot;">​</a></h2><p>提示是在問題中把要求寫清楚; 檢索是讓模型先查自己的文件再回答; 微調則是用自己的資料再訓練模型. 可以想成帶新同事: 提示是把工作交代清楚, 檢索是給一份手冊讓對方隨時查, 微調則是送去受訓. 三者需要投入的資料與算力依序增加 (推論, 信心: 中).</p><p>待撰寫要點:</p><ul><li>先用提示與檢索(M4)解決, 仍不足才考慮微調</li><li>決策流程圖</li></ul><h2 id="t1-2-資料準備與品質檢查" tabindex="-1">T1.2 資料準備與品質檢查 <a class="header-anchor" href="#t1-2-資料準備與品質檢查" aria-label="Permalink to &quot;T1.2 資料準備與品質檢查&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>資料量, 格式與標註品質</li><li>個人資料與機密資料的處理</li></ul><h2 id="t1-3-成本與時間估算" tabindex="-1">T1.3 成本與時間估算 <a class="header-anchor" href="#t1-3-成本與時間估算" aria-label="Permalink to &quot;T1.3 成本與時間估算&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>依硬體等級估算微調所需時間與記憶體</li><li>與持續使用雲端 API 的成本比較</li></ul><h2 id="資料來源" tabindex="-1">資料來源 <a class="header-anchor" href="#資料來源" aria-label="Permalink to &quot;資料來源&quot;">​</a></h2><p>本章目前只有章節大綱, 沒有數字, 版本, 授權或評測分數等事實性陳述, 因此未列外部來源.</p><ul><li><strong>「先用提示與檢索 (M4) 解決, 仍不足才考慮微調」</strong>: 整理者的建議順序 (推論, 信心: 中), 依據見 <a href="/lanai-handbook/build/m4-retrieval">M4 檢索</a>.</li><li><strong>「三者需要投入的資料與算力依序增加」</strong>: 整理者推論 (信心: 中), 撰寫 T1.3 時以實際估算佐證.</li><li><strong>文中的類比 (帶新同事)</strong>: 整理者所寫, 無外部來源, 不應當作技術定義引用.</li><li><strong>撰寫時的來源要求</strong>: T1.3 的硬體時間, 記憶體估算與雲端 API 成本比較, 須附官方文件或實測紀錄; 數字可參考 <a href="/lanai-handbook/train/t2-finetune">T2</a> 已整理的 QLoRA 顯示記憶體需求與<a href="/lanai-handbook/decide/tco">成本試算表</a>的框架.</li></ul>',16)])])}const _=t(r,[["render",o]]);export{p as __pageData,_ as default};
